fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Since we assume arr1 and arr2 have the same length,
    // we can safely zip them together.
    arr1.iter()
        .zip(arr2.iter())
        .map(|(a, b)| a - b)
        .collect()
}

